function normalizeSpeciesName(s) {
  return String(s || '').toLowerCase()
    .replace(/[\u2642]/g, ' m').replace(/[\u2640]/g, ' f')
    .replace(/[^a-z0-9]+/g, ' ').trim().replace(/\s+/g, '-');
}
const NAME_TO_DEX = {};
Object.keys(DEX_NAMES).forEach(dex => { NAME_TO_DEX[normalizeSpeciesName(DEX_NAMES[dex])] = Number(dex); });
// Default-form suffix a bare species name should resolve to when the table
// only has a hyphenated form name (e.g. "Shaymin" -> "shaymin-land", not
// "shaymin-sky"). Order is priority: first suffix found among the candidates wins.
const DEFAULT_FORM_SUFFIXES = ['land', 'normal', 'incarnate', 'standard', 'altered', 'average', 'red-striped', 'aria', 'ordinary', 'shield', 'disguised', 'plant', 'male', 'baile', 'midday', 'solo', 'z'];
function resolveDexByName(name) {
  const norm = normalizeSpeciesName(name);
  if (NAME_TO_DEX[norm] != null) return NAME_TO_DEX[norm];
  const loose = norm.replace(/-/g, '');
  for (const key in NAME_TO_DEX) {
    if (key.replace(/-/g, '') === loose) return NAME_TO_DEX[key];
  }
  // Bare species name against a table that only has "name-form" entries
  // (Shaymin, Giratina, etc. are stored under their default form's key).
  const prefixMatches = Object.keys(NAME_TO_DEX).filter(key => key.startsWith(norm + '-'));
  if (prefixMatches.length) {
    for (const suf of DEFAULT_FORM_SUFFIXES) {
      const hit = prefixMatches.find(key => key === norm + '-' + suf);
      if (hit) return NAME_TO_DEX[hit];
    }
    if (prefixMatches.length === 1) return NAME_TO_DEX[prefixMatches[0]];
  }
  return null;
}


function cpFor(base, ivs, level) {
  const cpm = CPM[level];
  if (!cpm) return null;
  const atk = base[0] + ivs[0], def = base[1] + ivs[1], sta = base[2] + ivs[2];
  return Math.max(10, Math.floor((atk * Math.sqrt(def) * Math.sqrt(sta) * cpm * cpm) / 10));
}

function hpFor(base, staIV, level) {
  const cpm = CPM[level];
  if (!cpm) return null;
  return Math.max(10, Math.floor((base[2] + staIV) * cpm));
}

function statProductFor(base, ivs, level) {
  const cpm = CPM[level];
  const atk = (base[0] + ivs[0]) * cpm;
  const def = (base[1] + ivs[1]) * cpm;
  const hp = Math.max(10, Math.floor((base[2] + ivs[2]) * cpm));
  return atk * def * hp;
}

// Stardust cost to Power Up, keyed by the level a Pokemon is AT (i.e. the
// cost to go from this level to the next half-level up). This is the public,
// community-verified Power-Up cost table (the same one PokeGenie/CalcyIV use),
// cross-validated against 66 real (dust, CP/HP-solved level) pairs pulled from
// this app's own users' actual rosters \u2014 94% (62/66) landed the true level
// inside the range this table predicts.
//
// Earlier version of this table was WRONG: it assumed each dust cost spans
// only 2 half-levels (1 full level). In reality each dust cost spans 4
// half-levels (2 full levels), which made every prior lookup come out at
// roughly HALF the Pokemon's true level. Levels 41+ require Candy XL instead
// of regular Candy but the dust progression continues the same pattern.
// GENERATED BLOCK — do not hand-edit. `scripts/update_pokemon_data.py` rewrites
// this list every week from pogoapi.net's powerup-requirements table, which is
// republished from Niantic's GAME_MASTER (the same source PokeGenie and CalcyIV
// read). It lists the first level of each Stardust tier; the tiers are derived
// from the per-half-level costs rather than assumed to span four half-levels
// each, so a cost-curve change is picked up automatically.
//
// This was hand-typed before, and the level 41+ entries
// (12000/15000/19000/22000/25000) were wrong — the real cost at level 49 is
// 15000. A wrong tier filters the IV solve to the wrong levels and discards the
// true spread, which is why it is now generated. Until the first refresh runs,
// only levels 1–40.5 (verified against Bulbapedia) are listed; a 41+ cost fails
// the 5% tolerance below, returns [], and the caller solves unrestricted.
const _DUST_TIER_START_LEVEL = [
  [1.0, 200], [3.0, 400], [5.0, 600], [7.0, 800], [9.0, 1000],
  [11.0, 1300], [13.0, 1600], [15.0, 1900], [17.0, 2200], [19.0, 2500],
  [21.0, 3000], [23.0, 3500], [25.0, 4000], [27.0, 4500], [29.0, 5000],
  [31.0, 6000], [33.0, 7000], [35.0, 8000], [37.0, 9000], [39.0, 10000],
  [41.0, 11000], [43.0, 12000], [45.0, 13000], [47.0, 14000], [49.0, 15000],
];

// dust value -> [levels...] that cost exactly that much to power up from.
// Each tier spans 4 consecutive half-levels starting at its listed level.
const _STARDUST_TO_LEVELS = (() => {
  const map = {};
  _DUST_TIER_START_LEVEL.forEach(([start, dust]) => {
    const levels = [0, 1, 2, 3].map(k => start + 0.5 * k);
    (map[dust] = map[dust] || []).push(...levels);
  });
  return map;
})();

// Reverses an OCR'd "Power Up" stardust cost into the small set of Pokemon
// levels that could produce it, undoing the lucky/shadow/purified cost
// multipliers first. Returns [] when the cost can't be matched (bad OCR,
// already-maxed Pokemon showing no Power Up button, or the ambiguous 15000
// plateau) \u2014 callers should treat an empty result as "no extra info",
// not as an error.
function levelsForPowerUpDust(observedDust, opts) {
  if (observedDust == null || !Number.isFinite(observedDust)) return [];
  opts = opts || {};
  let mult = 1;
  if (opts.lucky) mult *= 0.5;
  if (opts.shadow) mult *= 1.2;
  if (opts.purified) mult *= 0.9;
  const normalized = observedDust / mult;
  // In-game costs round to the nearest displayed value; allow a small
  // tolerance around the multiplier reversal rather than requiring exact
  // floating-point equality.
  let best = null, bestDiff = Infinity;
  for (const dustKey of Object.keys(_STARDUST_TO_LEVELS)) {
    const diff = Math.abs(Number(dustKey) - normalized);
    if (diff < bestDiff) { bestDiff = diff; best = dustKey; }
  }
  if (best == null || bestDiff > Number(best) * 0.05) return [];
  return _STARDUST_TO_LEVELS[best].slice();
}

// Brute-force every level/IV combo matching an observed CP and HP exactly.
// `hint` optionally narrows the result using what the in-game appraisal shows:
//   { stars: 0-4, maxed: ['atk','def','sta'] }
// Star tiers are total-IV bands, and a "maxed" bar means that stat is exactly
// 15. CP+HP alone often leaves dozens of spreads on low-CP Pokemon; the
// appraisal collapses that to one or two without needing exact printed numbers.
// `levelFilter`, if given, restricts the search to only those levels (e.g.
// the 1-2 levels implied by an OCR'd Power Up stardust cost via
// levelsForPowerUpDust) instead of every level 1-51 \u2014 the same kind of
// narrowing an appraisal gives, but derived from a number visible on every
// detail screen instead of a separate appraisal screen.
function solveIVs(base, cp, hp, hint, levelFilter) {
  const candidates = [];
  let levels = Object.keys(CPM).map(Number).sort((a, b) => a - b);
  if (Array.isArray(levelFilter) && levelFilter.length) {
    const allowed = new Set(levelFilter);
    levels = levels.filter(l => allowed.has(l));
  }
  for (const level of levels) {
    for (let staIV = 0; staIV <= 15; staIV++) {
      if (hpFor(base, staIV, level) !== hp) continue;
      for (let atkIV = 0; atkIV <= 15; atkIV++) {
        for (let defIV = 0; defIV <= 15; defIV++) {
          if (cpFor(base, [atkIV, defIV, staIV], level) === cp) {
            candidates.push({ level, atkIV, defIV, staIV });
          }
        }
      }
    }
  }
  return hint ? filterByAppraisal(candidates, hint) : candidates;
}

// Total-IV range for each appraisal star tier.
const STAR_BANDS = [[0, 22], [23, 29], [30, 36], [37, 44], [45, 45]];

function filterByAppraisal(candidates, hint) {
  if (!hint) return candidates;
  const band = Number.isInteger(hint.stars) ? STAR_BANDS[hint.stars] : null;
  const maxed = Array.isArray(hint.maxed) ? hint.maxed : [];
  const useMaxed = !!hint.maxedKnown;
  const out = candidates.filter(c => {
    if (band) {
      const total = c.atkIV + c.defIV + c.staIV;
      if (total < band[0] || total > band[1]) return false;
    }
    // A highlighted bar means that stat is 15; a bar the user did NOT mark must
    // therefore be below 15, which is what makes this so effective.
    if (useMaxed) {
      if (maxed.includes('atk') !== (c.atkIV === 15)) return false;
      if (maxed.includes('def') !== (c.defIV === 15)) return false;
      if (maxed.includes('sta') !== (c.staIV === 15)) return false;
    }
    return true;
  });
  // A hint that matches nothing is INFORMATION, not noise: it means the
  // appraisal contradicts the CP/HP, so one of the three was misread. Silently
  // returning the unfiltered set made the feature look like a no-op (a 3-star
  // hint on an 84-candidate Rookidee still gave 84) and told the user to add
  // more input when what they gave had been thrown away. Keep the full set so
  // nothing is lost, but flag the contradiction.
  if (!out.length) {
    const all = candidates.slice();
    all.hintMismatch = true;
    return all;
  }
  return out;
}

// Best possible stat product for a species at/under a league's CP cap, searched
// across ALL 4096 IV spreads. Using 15/15/15 as the reference is wrong for
// capped leagues: a lower-attack spread reaches a higher level under the cap and
// produces a HIGHER stat product, which made real Pokemon rank above 100%.
//
// isShadow controls the STAT PRODUCT side only (the numerator/denominator of
// the rank%), never the CP-cap eligibility test: Niantic does not change a
// shadow's displayed/legal CP, only its battle damage, so which levels fit
// under the cap is always computed from the real (unmodified) base stats.
// Ranking a shadow against a shadow ceiling (not the normal-form ceiling)
// keeps the comparison apples-to-apples, same as PvPoke's methodology.
const _bestSPCache = new Map();
// Highest level PvP ranks may use. PvPoke and most IV tools default to 50;
// 51 is a best-buddy boost, and 40 is what a player without XL Candy can reach.
let _pvpMaxLevel = 50;
function setPvpMaxLevel(n) {
  const v = Number(n);
  if (v === 40 || v === 50 || v === 51) _pvpMaxLevel = v;
}
function getPvpMaxLevel() { return _pvpMaxLevel; }
function _pvpLevels() {
  return Object.keys(CPM).map(Number).filter(l => l <= _pvpMaxLevel).sort((a, b) => a - b);
}
function bestStatProductUnderCap(base, capCP, isShadow) {
  // base is an array [atk, def, sta] — an object-style key collides across species.
  const key = (Array.isArray(base) ? base.join('_') : [base.atk, base.def, base.sta].join('_')) + '|' + capCP + '|' + (isShadow ? 's' : 'n') + '|' + _pvpMaxLevel;
  const hit = _bestSPCache.get(key);
  if (hit !== undefined) return hit;
  const sBase = shadowAdjustedBase(base, isShadow);
  const levels = _pvpLevels();
  let best = 0;
  for (let atkIV = 0; atkIV <= 15; atkIV++) {
    for (let defIV = 0; defIV <= 15; defIV++) {
      for (let staIV = 0; staIV <= 15; staIV++) {
        const ivs = [atkIV, defIV, staIV];
        // Levels ascend, so walk down from the top and take the first legal one.
        for (let i = levels.length - 1; i >= 0; i--) {
          if (cpFor(base, ivs, levels[i]) <= capCP) {
            const sp = statProductFor(sBase, ivs, levels[i]);
            if (sp > best) best = sp;
            break;
          }
        }
      }
    }
  }
  _bestSPCache.set(key, best);
  return best;
}

// This Pokemon's own best stat product at/under a league cap, searching all legal levels for its fixed IVs.
function ownBestStatProductUnderCap(base, ivs, capCP, isShadow) {
  const sBase = shadowAdjustedBase(base, isShadow);
  const levels = _pvpLevels();
  for (let i = levels.length - 1; i >= 0; i--) {
    if (cpFor(base, ivs, levels[i]) <= capCP) return statProductFor(sBase, ivs, levels[i]);
  }
  return 0;
}

// The single best IV spread for a league and where it lands: { ivs, level, product }.
// Because stat product multiplies ATK x DEF x HP and the CP cap limits the total,
// the best spread under a cap usually has LOW attack (more of the CP budget goes
// to defence and HP). Under no cap (Master League) it is 15/15/15.
const _bestSpreadCache = new Map();
function bestSpreadUnderCap(base, capCP, isShadow) {
  const key = (Array.isArray(base) ? base.join('_') : [base.atk, base.def, base.sta].join('_')) + '|' + capCP + '|' + (isShadow ? 's' : 'n') + '|' + _pvpMaxLevel;
  const hit = _bestSpreadCache.get(key);
  if (hit !== undefined) return hit;
  const sBase = shadowAdjustedBase(base, isShadow);
  const levels = _pvpLevels();
  let best = null;
  for (let a = 0; a <= 15; a++) for (let d = 0; d <= 15; d++) for (let h = 0; h <= 15; h++) {
    const ivs = [a, d, h];
    for (let i = levels.length - 1; i >= 0; i--) {
      if (cpFor(base, ivs, levels[i]) <= capCP) {
        const sp = statProductFor(sBase, ivs, levels[i]);
        if (!best || sp > best.product) best = { ivs, level: levels[i], product: sp };
        break;
      }
    }
  }
  _bestSpreadCache.set(key, best);
  return best;
}

function rankPctForLeague(base, ivs, leagueKey, isShadow) {
  const cap = LEAGUE_CAPS[leagueKey];
  const own = ownBestStatProductUnderCap(base, ivs, cap, isShadow);
  const max = bestStatProductUnderCap(base, cap, isShadow);
  if (!(max > 0)) return null;
  // Clamp: floating-point noise can nudge an optimal spread a hair over 100.
  return Math.min(100, (own / max) * 100);
}

// GENERATED BLOCK — do not hand-edit. Full Power-Up cost curve, run-length
// encoded as [firstLevelOfRun, stardust, candy, xlCandy] where each run covers
// consecutive half-levels until the next run starts. Pulled from pogoapi.net's
// pokemon_powerup_requirements endpoint (republished from Niantic's
// GAME_MASTER) — the same source _DUST_TIER_START_LEVEL above comes from, and
// consistent with it. Level 40+ costs XL Candy instead of regular Candy, which
// is why xlCandy is a separate column rather than a conversion.
// The cost listed at level L is the cost to go from L to L+0.5. Level 50 is the
// cap, so there is no run starting at 50.
const _POWERUP_RUNS = [
  [1, 200, 1, 0], [3, 400, 1, 0], [5, 600, 1, 0], [7, 800, 1, 0], [9, 1000, 1, 0],
  [11, 1300, 2, 0], [13, 1600, 2, 0], [15, 1900, 2, 0], [17, 2200, 2, 0], [19, 2500, 2, 0],
  [21, 3000, 3, 0], [23, 3500, 3, 0], [25, 4000, 3, 0], [26, 4000, 4, 0], [27, 4500, 4, 0],
  [29, 5000, 4, 0], [31, 6000, 6, 0], [33, 7000, 8, 0], [35, 8000, 10, 0], [37, 9000, 12, 0],
  [39, 10000, 15, 0], [40, 10000, 0, 10], [41, 11000, 0, 10], [42, 11000, 0, 12],
  [43, 12000, 0, 12], [44, 12000, 0, 15], [45, 13000, 0, 15], [46, 13000, 0, 17],
  [47, 14000, 0, 17], [48, 14000, 0, 20], [49, 15000, 0, 20]
];
const MAX_POKEMON_LEVEL = 50;

// Cost of the single Power Up that takes a Pokemon from `level` to level+0.5.
function powerUpStepCost(level) {
  if (!(level >= 1) || level >= MAX_POKEMON_LEVEL) return null;
  let run = null;
  for (const r of _POWERUP_RUNS) { if (r[0] <= level) run = r; else break; }
  if (!run) return null;
  return { dust: run[1], candy: run[2], xlCandy: run[3] };
}

// Total cost to walk a Pokemon from one level to another, half-level by
// half-level. Lucky halves Stardust, Shadow adds 20%, Purified takes 10% off —
// the multipliers apply to Stardust and Candy, never to XL Candy.
function powerUpCostBetween(fromLevel, toLevel, opts) {
  opts = opts || {};
  const out = { dust: 0, candy: 0, xlCandy: 0, steps: 0, reachable: true };
  if (!(fromLevel >= 1) || !(toLevel >= 1)) { out.reachable = false; return out; }
  if (toLevel <= fromLevel) return out;
  // Lucky is Stardust-only in the real game \u2014 candy cost is unaffected.
  // Shadow (+20%) and Purified (-10%) apply to BOTH, and are allowed to stack
  // with Lucky (e.g. a Lucky Purified Pokemon gets 0.5 * 0.9 = 45% Stardust).
  let dustMult = 1, candyMult = 1;
  if (opts.lucky) dustMult *= 0.5;
  if (opts.shadow) { dustMult *= 1.2; candyMult *= 1.2; }
  if (opts.purified) { dustMult *= 0.9; candyMult *= 0.9; }
  for (let lv = fromLevel; lv < Math.min(toLevel, MAX_POKEMON_LEVEL); lv += 0.5) {
    const step = powerUpStepCost(lv);
    if (!step) { out.reachable = false; break; }
    out.dust += Math.round(step.dust * dustMult);
    out.candy += Math.round(step.candy * candyMult);
    out.xlCandy += step.xlCandy;
    out.steps++;
  }
  return out;
}

// Highest level this exact spread can reach without breaking a league's CP cap.
// Returns null when even level 1 is already over the cap (common for fully
// evolved Pokemon in Little Cup).
function maxLevelUnderCap(base, ivs, capCP) {
  if (!(capCP > 0) || !Number.isFinite(capCP)) return MAX_POKEMON_LEVEL;
  const levels = Object.keys(CPM).map(Number).filter(l => l <= MAX_POKEMON_LEVEL).sort((a, b) => a - b);
  for (let i = levels.length - 1; i >= 0; i--) {
    if (cpFor(base, ivs, levels[i]) <= capCP) return levels[i];
  }
  return null;
}

// Raw-stat attacker score. There is no move data in this app, so this is
// deliberately NOT a DPS figure: it is effective Attack at the given level,
// lightly weighted by bulk so a glass cannon doesn't outrank a Pokemon that
// survives long enough to use its charge move. Ranking within a type is what
// this is for; the absolute number means nothing on its own.
// isShadow applies the same +20% ATK / -16.667% DEF adjustment rankPctForLeague
// uses \u2014 without it, shadow Pokemon (which hit harder in real battle) were
// silently under-ranked here and on every raid/attacker screen that reads it.
function attackerScore(base, ivs, level, isShadow) {
  const cpm = CPM[level != null ? level : 40];
  if (!cpm) return 0;
  const sBase = shadowAdjustedBase(base, isShadow);
  const atk = (sBase[0] + ivs[0]) * cpm;
  const def = (sBase[1] + ivs[1]) * cpm;
  const sta = (sBase[2] + ivs[2]) * cpm;
  return Math.pow(atk, 0.8) * Math.pow(def * sta, 0.2);
}

