// Real-data lookup by lowercase species name. Returns null if uncovered
// (unreleased species, unusual forms) so callers fall back to an
// unrestricted search rather than blocking on missing data.
function movepoolFor(name) {
  return MOVEPOOL_TABLE[String(name || '').toLowerCase()] || null;
}

