// Real-data lookup by lowercase species name. Returns null if this species
// isn't covered (new species before a GAME_MASTER update, unusual forms) —
// callers fall back to their own AI-guessed table in that case.
function evolutionInfoFor(name) {
  return REAL_EVOLUTION_TABLE[String(name || '').toLowerCase()] || null;
}

