const STAB_MULTIPLIER = 1.2;
// Ranking DPS with no particular defender in mind still needs a defence number
// to divide by. 200 is roughly a mid-tier raid boss; because it is the same
// constant for every Pokemon it cancels out of the ordering entirely and only
// affects the absolute figure.
const REFERENCE_DEFENCE = 200;

function typeMultiplier(attackType, defenderTypes) {
  if (!attackType) return 1;
  const row = TYPE_CHART[attackType];
  if (!row || !Array.isArray(defenderTypes) || !defenderTypes.length) return 1;
  return defenderTypes.reduce((m, t) => m * (row[t] != null ? row[t] : 1), 1);
}

// One hit's damage, using Niantic's formula. `move` is a record from the move
// database: { type, power, energy, durationMs }.
// Weather boosts damage of moves whose type matches by 20%.
const WEATHER_BOOST = 1.2;
const WEATHER_TYPES = {
  'Sunny': ['Grass', 'Ground', 'Fire'],
  'Rainy': ['Water', 'Electric', 'Bug'],
  'Partly cloudy': ['Normal', 'Rock'],
  'Cloudy': ['Fairy', 'Fighting', 'Poison'],
  'Windy': ['Dragon', 'Flying', 'Psychic'],
  'Snow': ['Ice', 'Steel'],
  'Fog': ['Dark', 'Ghost']
};

function moveDamage(move, attackStat, ownTypes, defenderTypes, defenceStat, weatherTypes) {
  if (!move || !(move.power > 0)) return 0;
  const stab = Array.isArray(ownTypes) && ownTypes.indexOf(move.type) >= 0 ? STAB_MULTIPLIER : 1;
  const eff = typeMultiplier(move.type, defenderTypes);
  const wx = Array.isArray(weatherTypes) && weatherTypes.indexOf(move.type) >= 0 ? WEATHER_BOOST : 1;
  const def = defenceStat > 0 ? defenceStat : REFERENCE_DEFENCE;
  return Math.floor(0.5 * move.power * (attackStat / def) * stab * eff * wx) + 1;
}

// Sustained DPS over one full fast-move/charged-move cycle. Returns null when
// either move is missing from the database — the caller must fall back to a
// stat-only ranking rather than pretending a number exists.
// opts.isShadow applies the same +20% ATK adjustment attackerScore and
// rankPctForLeague use \u2014 omitting it understated every shadow Pokemon's
// real raid damage on the Attackers board and Raid Counters screen.
function cycleDps(base, ivs, level, fastMove, chargedMove, opts) {
  opts = opts || {};
  const cpm = CPM[level != null ? level : 40];
  if (!cpm || !fastMove || !chargedMove) return null;
  if (!(fastMove.durationMs > 0) || !(chargedMove.durationMs > 0)) return null;
  if (!(fastMove.energy > 0) || !(chargedMove.energy > 0)) return null;
  const sBase = shadowAdjustedBase(base, opts.isShadow);
  const atk = (sBase[0] + ivs[0]) * cpm;
  const dmgFast = moveDamage(fastMove, atk, opts.ownTypes, opts.defenderTypes, opts.defenceStat, opts.weatherTypes);
  const dmgCharged = moveDamage(chargedMove, atk, opts.ownTypes, opts.defenderTypes, opts.defenceStat, opts.weatherTypes);
  const fastPerCharged = Math.ceil(chargedMove.energy / fastMove.energy);
  const cycleMs = fastPerCharged * fastMove.durationMs + chargedMove.durationMs;
  const cycleDmg = fastPerCharged * dmgFast + dmgCharged;
  if (!(cycleMs > 0)) return null;
  return (cycleDmg / cycleMs) * 1000;
}

// Raid rating: how hard a Pokemon hits AND how long it lasts, for one specific
// fast + charged pairing. rating = DPS x (HP x DEF)^0.4.
//  - DPS is cycleDps (STAB, Shadow, real move data).
//  - HP x DEF stands in for survivability. A boss's damage rate is the same
//    number for every attacker, so it cancels out of any ordering and is left out.
//  - The 0.4 exponent is a design choice that mirrors the usual community
//    weighting of damage rate over survivability (about 60/40). It is an
//    approximation: no dodging, no energy gained from damage taken, no party
//    or weather bonuses, no boss-specific move timing.
// Returns { dps, hp, def, rating } or null when either move lacks data.
function raidRating(base, ivs, level, fastMove, chargedMove, opts) {
  opts = opts || {};
  const dps = cycleDps(base, ivs, level, fastMove, chargedMove, opts);
  if (dps == null) return null;
  const cpm = CPM[level != null ? level : 40];
  const sBase = shadowAdjustedBase(base, opts.isShadow);
  const def = (sBase[1] + ivs[1]) * cpm;
  const hp = Math.max(10, Math.floor((sBase[2] + ivs[2]) * cpm));
  return { dps, hp, def, rating: dps * Math.pow(hp * def, 0.4) };
}

